	BlockVehicleSetting,
	ResolvedPhysicsSettings,
	ByBlockRecordKey,
	DefaultPhysicsTypeSettings,
	AllPhysicsSettings,
	ImpactCameraShakeOpts,
	SteeringOpts,
	FluidSkipOpts,
	AirborneModeOpts,
	AirborneMovementOpts,
	FallSpeedLimitOpts,
	HeadingAirborneMovement,
	CameraDirectionAirborneMovement,
	PerBlockVehicleSetting,
	VehicleSettingValue,
	BlockVehicleSettingValue,
	PerBlockVehicleSettingValue,
	MeshEntityVehicleType,
	VehicleSpawnOpts,
	AngleDir,
	BlockRaycastResult,
	MeshParticleSystemUpdates,
	MeshParticleSystemUpdate,
	UgcCurrencyInfo,
	UserCallbacks,
	WorldGamemode,
	QueuedCommandId,
	QueuedStatusString,
	UiRequestClientParameters,
	MultiBlockInfo,
	BoughtShopItem,
	OnPlayerChatObjectResponse,
	ChatMessageObject,
	FishingAttemptOptions,
	_TypeOf,
	ItemMetaInfo,
	BlockMetadataItem,
	NonBlockMetadataItem,
	LoadedChunk,
	Song,
	ParticleSystemBlendMode,
	HalfblockPlacement,
	WalkThroughType,
	LobbyType,
	PhysicsType,
	BoatTier,
	GliderTier,
	BalloonTier,
	SleepingTier,
	CarTier,
